"use client";

import { useEffect, useRef, useState } from "react";
import dynamic from "next/dynamic";
import { TerminalSquare } from "lucide-react";
import { Tooltip } from "@/components/ui/tooltip";

// The palette's guts (cmdk, Radix dialog, voice picker/settings, and the
// content-corpus-backed action lists) are ~140KB and only ever needed after
// the first ⌘K / click — kept off the initial bundle the same way
// ask-portfolio.tsx keeps its markdown renderer off the initial bundle.
const CommandPaletteContent = dynamic(
  () =>
    import("@/components/command-palette-content").then(
      (m) => m.CommandPaletteContent,
    ),
  { ssr: false },
);

type CommandPaletteProps = {
  discoveryBadgesEnabled: boolean;
};

export function CommandPalette({
  discoveryBadgesEnabled,
}: CommandPaletteProps) {
  const [loaded, setLoaded] = useState(false);
  const [open, setOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);

  // This listener is the whole reason the shell stays mounted eagerly: most
  // ⌘K presses happen before the user has ever clicked the trigger pill.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "k" && (e.metaKey || e.ctrlKey)) {
        e.preventDefault();
        setLoaded(true);
        setOpen((o) => !o);
      }
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, []);

  return (
    <>
      {/* Trigger pill — bottom-right, terminal-styled */}
      <Tooltip content="Open command palette (⌘K)">
        <button
          ref={triggerRef}
          onClick={() => {
            setLoaded(true);
            setOpen(true);
          }}
          aria-label="Open command palette"
          className="fixed bottom-5 right-5 z-40 inline-flex items-center gap-2 rounded-lg border border-border-strong bg-bg-surface/90 px-3 py-2 font-mono text-xs text-fg-muted shadow-lg backdrop-blur transition-colors hover:border-accent hover:text-fg"
        >
          <TerminalSquare size={14} className="text-accent" />
          <span className="hidden sm:inline">Command</span>
          <kbd
            aria-keyshortcuts="Meta+K"
            aria-hidden="true"
            className="rounded bg-bg-elevated px-1.5 py-0.5 text-[10px]"
          >
            ⌘K
          </kbd>
        </button>
      </Tooltip>

      {/* Mounted once loaded and left mounted (never unmounted again) so its
          own open/close state, recents, and dialogs behave exactly as if it
          had been here from the start. */}
      {loaded && (
        <CommandPaletteContent
          discoveryBadgesEnabled={discoveryBadgesEnabled}
          open={open}
          onOpenChange={setOpen}
          triggerRef={triggerRef}
        />
      )}
    </>
  );
}
"use client";

import { ArrowLeft, FileText } from "lucide-react";
import { useView } from "@/components/view-context";

/**
 * The recruiter escape hatch present on every non-classic view. Rendered as the
 * FIRST focusable element so neither the gamified nor chat experience can become a
 * keyboard trap: a visitor can always jump straight back to the indexed Classic
 * page or to the résumé. "Back to Classic" is a view switch (no navigation);
 * "Résumé" is a real link so it works even if JS for the view fails.
 */
export function ViewEscapeHatch() {
  const { setView } = useView();
  return (
    <div className="flex items-center gap-2">
      <button
        type="button"
        onClick={() => setView("classic")}
        className="inline-flex items-center gap-1.5 rounded-full border border-border px-3 py-1.5 text-xs font-medium text-fg-muted transition-colors hover:border-accent hover:text-fg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"
      >
        <ArrowLeft size={13} aria-hidden="true" />
        Back to Classic
      </button>
      <a
        href="/resume"
        className="inline-flex items-center gap-1.5 rounded-full border border-border px-3 py-1.5 text-xs font-medium text-fg-muted transition-colors hover:border-accent hover:text-fg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"
      >
        <FileText size={13} aria-hidden="true" />
        Résumé
      </a>
    </div>
  );
}
"use client";

import { useState } from "react";
import { Sparkles, Send } from "lucide-react";
import { useChat } from "@/components/chat/use-chat";
import {
  RECRUITER_CHIPS,
  STARTER_CHIPS,
} from "@/components/chat/chat-suggestions";
import { ChatMessages } from "@/components/chat/chat-messages";
import { MicButton } from "@/components/chat/mic-button";
import { TalkLaunchButton } from "@/components/chat/talk-launch-button";
import { FilePickerButton } from "@/components/chat/file-picker-button";
import { AttachmentPreviewStrip } from "@/components/chat/attachment-preview-strip";
import { ViewEscapeHatch } from "@/components/view-escape-hatch";
import { profile, impactMetrics } from "@/lib/profile";
import { OPEN_TO_WORK } from "@/lib/writing-flags";
import { cn } from "@/lib/utils";

/**
 * AI-CHAT view — a full "concierge console", not a bare chat box. Opens answer-
 * first: identity + impact strip + a persistent recruiter chip-rail so the
 * strongest-work / GenAI / impact answers are one tap. Reuses the existing Bedrock
 * backend (/api/chat -> streamWithFallback) untouched via the useChat transport.
 *
 * The escape hatch is the FIRST focusable element (never a keyboard trap). Full
 * a11y (aria-live announce-on-settle, Stop, pin-aware autoscroll) lands in 2.3.
 */
export function ChatView() {
  const { messages, send, stop, isStreaming, pendingFiles, setPendingFiles } =
    useChat();
  const [input, setInput] = useState("");
  const empty = messages.length === 0;

  const onSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    send(input, pendingFiles.length > 0 ? pendingFiles : undefined);
    setInput("");
    setPendingFiles([]);
  };

  const ask = (q: string) => {
    if (isStreaming) return;
    send(q, []);
    setInput("");
  };

  return (
    // Fixed height (not min-h): the console must be a BOUNDED flex container so the
    // transcript scrolls INTERNALLY. With only min-height the element is content-sized
    // and unbounded, so a tall conversation grows the document and the inner
    // overflow-y-auto never engages (the autoscroll snap then no-ops). `dvh` (not vh)
    // keeps the composer clear of iOS Safari's address bar. Also subtracts the
    // OpenToWorkBanner's height when it's showing — otherwise this exact-height <main>
    // is permanently taller than the viewport by exactly the banner's height, forcing a
    // scrollbar with nothing extra to scroll to. Both variants must be literal Tailwind
    // class strings (not built via template interpolation) — the JIT scanner only
    // detects arbitrary-value classes that appear verbatim in source; see
    // OPEN_TO_WORK_BANNER_HEIGHT_REM in writing-flags.ts for where 2.3125rem comes from.
    <main
      className={cn(
        "mx-auto flex w-full max-w-3xl flex-col px-6 py-6",
        OPEN_TO_WORK
          ? "h-[calc(100dvh-3.5rem-2.3125rem)]"
          : "h-[calc(100dvh-3.5rem)]",
      )}
    >
      <div className="flex items-center justify-between gap-3">
        <ViewEscapeHatch />
        <div className="flex items-center gap-3">
          {/* Hands-free voice conversation (modal surface; null on the 5th-view surface
              or unsupported browsers). */}
          <TalkLaunchButton />
          <p className="inline-flex items-center gap-1.5 font-mono text-xs uppercase tracking-widest text-accent">
            <Sparkles size={13} aria-hidden="true" /> AI Concierge
          </p>
        </div>
      </div>

      {/* Bordered "console" panel — frames the whole conversation so it reads as a
          contained concierge terminal, not scattered elements in an empty void. */}
      {/* min-h-0 lets this flex child shrink below its content so the transcript
          (the flex-1 child below) can own the overflow instead of pushing the page. */}
      <section className="mt-4 flex min-h-0 flex-1 flex-col rounded-2xl border border-border-strong bg-bg-surface/40 p-5 shadow-xl shadow-black/20 backdrop-blur sm:p-6">
        {/* Answer-first greeting + verified impact strip (recruiter visual triage).
          min-h-0 + overflow-y-auto + shrink: on a SHORT viewport this tall block (greeting +
          6-tile metric grid) must scroll WITHIN itself rather than push the composer out of
          the bordered console (it was a rigid flex sibling, so it shoved the composer + caption
          past the section border). It collapses to nothing once a conversation starts (empty). */}
        {empty && (
          <header className="min-h-0 shrink overflow-y-auto">
            <h1 className="text-2xl font-semibold tracking-tight">
              Ask me anything about {profile.name.split(" ")[0]}&apos;s work
            </h1>
            <p className="mt-2 max-w-xl text-sm text-fg-muted">
              Grounded in real projects and production systems — GenAI, backend,
              and open source. I answer in the first person and never invent
              details.
            </p>
            <dl className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-3">
              {impactMetrics.map((m) => (
                <div
                  key={m.label + m.sub}
                  className="rounded-xl border border-border bg-bg-surface/60 px-3 py-2.5"
                >
                  {/* dt = term (the metric), dd = description (its value+context) */}
                  <dt className="font-mono text-lg font-semibold text-fg">
                    {m.value}
                  </dt>
                  <dd className="text-xs text-fg-muted">{m.label}</dd>
                  <dd className="text-[11px] text-fg-subtle">{m.sub}</dd>
                </div>
              ))}
            </dl>
          </header>
        )}

        {/* Conversation. Grows to fill; messages + a11y live region live here (2.3). */}
        <ChatMessages messages={messages} isStreaming={isStreaming} />

        {/* Persistent recruiter chip-rail — one-tap strongest-work / impact paths.
          shrink-0: never let a short viewport compress the chips into the transcript. */}
        <div className="mt-4 shrink-0">
          <div
            className="flex flex-wrap gap-2"
            role="group"
            aria-label="Suggested questions"
          >
            {RECRUITER_CHIPS.map((c) => (
              <button
                key={c}
                type="button"
                onClick={() => ask(c)}
                disabled={isStreaming}
                className="rounded-full border border-border px-3 py-1.5 text-xs text-fg-muted transition-colors hover:border-accent hover:text-fg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent disabled:opacity-50"
              >
                {c}
              </button>
            ))}
          </div>
          {empty && (
            <div className="mt-2 flex flex-wrap gap-2">
              {STARTER_CHIPS.map((c) => (
                <button
                  key={c}
                  type="button"
                  onClick={() => ask(c)}
                  disabled={isStreaming}
                  className="rounded-full px-3 py-1.5 text-xs text-fg-subtle transition-colors hover:text-fg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent disabled:opacity-50"
                >
                  {c}
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Pending attachment previews — rendered above the composer when files are queued.
          Returns null when empty so there is no layout shift. */}
        <AttachmentPreviewStrip
          files={pendingFiles}
          onRemove={(i) =>
            setPendingFiles((prev) => {
              const removed = prev[i];
              if (removed?.previewUrl) URL.revokeObjectURL(removed.previewUrl);
              return prev.filter((_, idx) => idx !== i);
            })
          }
        />

        {/* Composer. shrink-0: the input the user types in must NEVER be compressed or
          pushed below the console border on a short viewport (it was escaping the section). */}
        <form
          onSubmit={onSubmit}
          className="mt-3 flex shrink-0 items-center gap-2"
        >
          <input
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Ask about my work, projects, or what I'm looking for…"
            aria-label="Ask a question about Sairam"
            className="flex-1 rounded-xl border border-border bg-bg-base px-4 py-3 text-sm outline-none placeholder:text-fg-muted focus:border-accent focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-1 focus-visible:ring-offset-bg-base"
          />
          {/* Push-to-talk mic — renders only where Web Speech is supported (else nothing,
            the text input is untouched). Transcripts fill the input for review. */}
          <MicButton onText={setInput} disabled={isStreaming} />
          {/* File attachment picker — feature-flagged via NEXT_PUBLIC_MULTIMODAL_ATTACHMENTS.
            Defaults to disabled so the button only appears when explicitly enabled. */}
          {process.env.NEXT_PUBLIC_MULTIMODAL_ATTACHMENTS === "true" && (
            <FilePickerButton
              onFiles={(f) =>
                setPendingFiles((prev) => [...prev, ...f].slice(0, 3))
              }
              disabled={isStreaming}
            />
          )}
          {isStreaming ? (
            <button
              type="button"
              onClick={stop}
              className="inline-flex h-11 items-center rounded-xl border border-border px-4 text-sm text-fg-muted transition-colors hover:border-accent hover:text-fg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent"
            >
              Stop
            </button>
          ) : (
            <button
              type="submit"
              disabled={!input.trim() && pendingFiles.length === 0}
              aria-label="Send"
              className="inline-flex h-11 w-11 items-center justify-center rounded-xl bg-accent text-bg-base transition-opacity disabled:opacity-40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-offset-1 focus-visible:ring-offset-bg-base"
            >
              <Send size={16} />
            </button>
          )}
        </form>
        <p className="mt-2 shrink-0 text-center text-[11px] text-fg-subtle">
          Grounded in real work · may simplify details
        </p>
      </section>
    </main>
  );
}

