@import "tailwindcss";

/*
  Design system — dark-technical "beast" base.
  Palette pairs deep ink backgrounds with an electric-cyan + violet accent,
  echoing the ContextOS/Graph-Forge dashboards. WCAG AA verified on bg-base.
*/
:root {
  color-scheme: dark;

  /* surfaces */
  --bg-base: #07080d;        /* page background */
  --bg-surface: #0d0f17;     /* cards */
  --bg-elevated: #141826;    /* hovered / elevated */
  --border: #1f2433;
  --border-strong: #2c3346;

  /* text */
  --fg: #e9ecf5;             /* primary text — 14.8:1 on bg-base */
  --fg-muted: #9aa3b8;       /* secondary — 6.9:1 on bg-base (AA) */
  --fg-subtle: #747e99;      /* tertiary / captions — 4.7:1 on bg-base (WCAG AA) */

  /* accents */
  --accent: #38e1ff;         /* electric cyan — links, focus, graph edges */
  --accent-strong: #0fb8db;
  --violet: #a78bfa;         /* secondary accent — AI/agent motifs */
  --green: #4ade80;          /* metrics up / success */
  --amber: #fbbf24;          /* highlights */

  /* effects */
  --glow-accent: 0 0 0 1px color-mix(in oklab, var(--accent) 35%, transparent),
                 0 0 24px -4px color-mix(in oklab, var(--accent) 45%, transparent);
}

/*
  Light theme override — applied via `document.documentElement.dataset.theme`
  (src/lib/theme-context.tsx), toggled by <ThemeToggle> in site-nav.tsx/mobile-nav.tsx.
  Re-declares every custom property from :root above so @theme inline's Tailwind
  mapping needs zero utility-class changes anywhere else in the app.

  OPEN RISK (not resolved by this change — flag in the PR): unlike the dark palette
  above, whose per-color contrast ratios are documented from direct verification,
  these light-mode values were chosen from standard accessible Tailwind-scale
  anchors (cyan-700 / violet-600 / green-700 / amber-700 range) but have NOT been run
  through an actual contrast checker against #f7f8fb / #ffffff. Verify before
  shipping — --green is the highest-risk hue for small text. --glow-accent needs no
  explicit override here (it resolves from whichever --accent is active via
  color-mix()), but the body gradient wash and skeleton shimmer were designed
  against the dark values and should be spot-checked visually under light mode.
*/
[data-theme="light"] {
  color-scheme: light;
  --bg-base: #f7f8fb; --bg-surface: #ffffff; --bg-elevated: #eef1f6;
  --border: #dde1ea; --border-strong: #c7ccd9;
  --fg: #12141c; --fg-muted: #4b5164; --fg-subtle: #6b7184;
  --accent: #0e7490; --accent-strong: #0b5b73; --violet: #7c3aed;
  --green: #15803d; --amber: #b45309;
}

@theme inline {
  --color-bg-base: var(--bg-base);
  --color-bg-surface: var(--bg-surface);
  --color-bg-elevated: var(--bg-elevated);
  --color-border: var(--border);
  --color-border-strong: var(--border-strong);
  --color-fg: var(--fg);
  --color-fg-muted: var(--fg-muted);
  --color-fg-subtle: var(--fg-subtle);
  --color-accent: var(--accent);
  --color-accent-strong: var(--accent-strong);
  --color-violet: var(--violet);
  --color-green: var(--green);
  --color-amber: var(--amber);

  --font-sans: var(--font-sans), ui-sans-serif, system-ui, sans-serif;
  --font-mono: var(--font-mono), ui-monospace, "SF Mono", monospace;

  --radius-card: 14px;
}

* {
  border-color: var(--border);
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  /* WCAG 2.2 SC 2.4.12 Focus Not Obscured: the sticky h-14 (3.5rem) header would
     otherwise cover a focused in-page anchor target. Pad the scroll position so the
     focused element lands below the header. */
  scroll-padding-top: 3.5rem;
  /* Defensive backstop: an un-contained overflowing descendant anywhere in the tree
     (e.g. a shrink-to-fit row wider than the viewport) would otherwise widen the whole
     document and cause page-level horizontal scroll/drag on mobile. Any element that
     genuinely needs horizontal scroll must opt in locally with its own overflow-x-auto
     container (see the articles filter bar) — this rule only clips the leak, it never
     hides content that has its own scroll container. */
  overflow-x: hidden;
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
}

/*
  Hero entrance — pure CSS, runs on first paint with NO JS/hydration gate, so the
  above-the-fold hero is never invisible-then-faded-in (that caused a load flicker
  and delayed LCP). Below-the-fold sections still use the JS-gated <Reveal>.
*/
@keyframes hero-rise {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: translateY(0); }
}
.hero-rise {
  opacity: 0;
  animation: hero-rise 0.5s cubic-bezier(0.21, 0.47, 0.32, 0.98) forwards;
}
@media (prefers-reduced-motion: reduce) {
  .hero-rise { opacity: 1; animation: none; }
}

/* Terminal cursor — cosmetic blink; solid (no animation) under reduced-motion. */
@keyframes terminal-blink { 0%, 49% { opacity: 1; } 50%, 100% { opacity: 0; } }
.terminal-cursor { animation: terminal-blink 1s steps(1) infinite; }
@media (prefers-reduced-motion: reduce) {
  .terminal-cursor { animation: none; opacity: 1; }
}

/* Terminal boot — one-time fade-in of the scrollback on mount (the "boot" feel).
   Text is fully in the DOM (screen-reader-safe); this only animates opacity. */
@keyframes terminal-boot { from { opacity: 0; } to { opacity: 1; } }
.terminal-boot { animation: terminal-boot 0.4s ease-out; }
@media (prefers-reduced-motion: reduce) {
  .terminal-boot { animation: none; }
}

/* Anvil header-orb idle — a FLUID, swirling, color-shifting Siri-style orb. The "metaball
   by blur+contrast" recipe: several conic-gradient color lobes painted on one pseudo, then
   fused by `filter: blur() contrast()` so they bleed + merge into liquid blobs (the contrast
   re-sharpens the blurred edges into rounded metaballs), with the conic `from` angle spun by
   a registered @property for the swirl, and a slow hue-rotate for the color shift — all in
   ONE filter chain (filter is a single property). PURE CSS, ZERO JS/rAF/WebGL/new-dep. COST:
   animating a @property angle is a per-frame MAIN-THREAD style-recalc + paint of the small
   ~38px pseudo (custom-property animation is NOT compositor-promoted) — negligible at this
   size and never the LCP element, but do NOT scale this recipe up while animated. The heavy
   3D orb only mounts inside the open voice surface. NOTE: NO mix-blend-mode — the conic
   layers self-fuse via overlap+contrast, which also sidesteps the WebKit backdrop-filter +
   descendant-blend glitch (bug 176830) under the header's backdrop-blur. isolation +
   overflow:hidden + translateZ(0) keep it on its own layer. Reduced-motion → a STATIC but
   still rich/fused orb (keeps blur+contrast — never `filter:none`, which would shatter the
   metaballs into hard arcs). Pre-Baseline browsers (Safari <16.4) ignore @property → the
   conic `from` is unset and the orb degrades to the solid `--accent-strong` disc + glow (a
   fine fallback, not the fused metaball). blur is tuned for the real 28px host, not a preview. */

@property --anvil-swirl {
  syntax: "<angle>";
  inherits: false;
  initial-value: 40deg;
}
@property --anvil-hue {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

@keyframes anvil-swirl-spin { to { --anvil-swirl: 400deg; } }
@keyframes anvil-hue-drift { to { --anvil-hue: 360deg; } }
@keyframes anvil-breathe {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.06); }
}

.anvil-orb-idle {
  position: relative;
  isolation: isolate;          /* own stacking context (keeps the fuse off the header backdrop) */
  overflow: hidden;            /* clip the fused blobs to the orb circle */
  border-radius: 9999px;
  background: var(--accent-strong); /* base wash behind the metaballs */
  box-shadow: 0 0 12px -2px color-mix(in oklab, var(--accent) 65%, transparent);
  animation: anvil-breathe 3.6s ease-in-out infinite;
}
/* The fluid layer: 4 conic color lobes at distinct off-center origins + signed swirl
   multipliers, fused by blur+contrast into liquid metaballs, hue-rotated for the shift. */
.anvil-orb-idle::before {
  content: "";
  position: absolute;
  inset: -25%;
  border-radius: 9999px;
  transform: translateZ(0);    /* promote to its own layer (Safari backdrop-root guard) */
  background:
    conic-gradient(from calc(var(--anvil-swirl) * 2)  at 32% 38%, var(--accent) 0deg, transparent 110deg),
    conic-gradient(from calc(var(--anvil-swirl) * -3) at 68% 36%, var(--violet, #a78bfa) 0deg, transparent 120deg),
    conic-gradient(from calc(var(--anvil-swirl) * 1)  at 40% 70%, color-mix(in oklab, var(--accent) 80%, white) 0deg, transparent 100deg),
    conic-gradient(from calc(var(--anvil-swirl) * -2) at 64% 66%, var(--accent-strong) 0deg, transparent 130deg);
  /* blur tuned for the REAL 28px host (~1.4px ≈ 5% of diameter) — fuses the lobes without
     washing them into a uniform smear; contrast re-sharpens into rounded metaballs. */
  filter: blur(1.4px) contrast(4.5) hue-rotate(var(--anvil-hue));
  animation:
    anvil-swirl-spin 18s linear infinite,
    anvil-hue-drift 22s linear infinite;
}
@media (prefers-reduced-motion: reduce) {
  .anvil-orb-idle,
  .anvil-orb-idle::before {
    animation: none;
  }
  /* Keep the fused metaballs (static): freeze the swirl at its balanced initial angle and
     KEEP blur+contrast (a one-time raster, free) + a fixed hue — never `filter: none`. */
  .anvil-orb-idle::before {
    filter: blur(1.4px) contrast(4.5) hue-rotate(0deg);
  }
}

body {
  background-color: var(--bg-base);
  color: var(--fg);
  font-family: var(--font-sans);
  /* Same backstop as html above — some mobile WebKit builds still rubber-band the body's
     own scrollable overflow even when the html root is clipped. Belt-and-suspenders only;
     the fix is containing overflow at its source (see the articles filter bar). */
  overflow-x: hidden;
}

/*
 * Faint technical grid + radial accent wash, isolated into a `position: fixed`
 * pseudo-element instead of `background-attachment: fixed` on body itself.
 * Chromium fails to repaint a fixed-attachment background once ANY element on the
 * page gets promoted to its own compositing layer (here: the sticky header's
 * `backdrop-blur-md`) — past roughly one viewport of scroll, the pattern silently
 * drops out entirely and never returns, on every page, not just long ones (verified
 * on both /resume and /projects). `position: fixed` on a dedicated layer sidesteps
 * that browser repaint path entirely; z-index: -1 keeps it behind all real content
 * without needing `body` to be a positioning context (fixed is viewport-relative
 * regardless of the ancestor chain, as long as nothing above it has its own
 * transform/filter/will-change/contain — none of html/body do here).
 */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  background-image:
    radial-gradient(60rem 40rem at 75% -10%, color-mix(in oklab, var(--violet) 9%, transparent), transparent 70%),
    radial-gradient(50rem 36rem at 5% 0%, color-mix(in oklab, var(--accent) 8%, transparent), transparent 70%),
    linear-gradient(to right, color-mix(in oklab, var(--border) 35%, transparent) 1px, transparent 1px),
    linear-gradient(to bottom, color-mix(in oklab, var(--border) 35%, transparent) 1px, transparent 1px);
  background-size: 100% 100%, 100% 100%, 56px 56px, 56px 56px;
}

/* focus-visible: keyboard nav (a11y).
   The .no-focus-ring opt-out is for elements that carry their OWN focus affordance
   (e.g. the ⌘K search row's focus-within border) — needed because this rule is
   UNLAYERED and would otherwise always beat any Tailwind utility (utilities live in
   @layer, and unlayered CSS wins the cascade regardless of specificity). */
/* WCAG 2.2 SC 2.4.11 Focus Appearance: a 3px outline (≥2px min) with offset gives a
   focus indicator whose contrast area clears the threshold against any background. */
:focus-visible:not(.no-focus-ring) {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

/* Skip-to-content link: visually hidden until focused, then the first interactive
   element so keyboard users can jump past the nav to the page content (a11y basic). */
.skip-link {
  position: fixed;
  top: 0.5rem;
  left: 0.5rem;
  z-index: 100;
  transform: translateY(-150%);
  transition: transform 0.15s ease;
  background: var(--bg-elevated);
  color: var(--fg);
  border: 1px solid var(--accent);
  border-radius: 8px;
  padding: 0.5rem 0.875rem;
  font-size: 0.875rem;
}
.skip-link:focus {
  transform: translateY(0);
}
@media (prefers-reduced-motion: reduce) {
  .skip-link {
    transition: none;
  }
}

::selection {
  background: color-mix(in oklab, var(--accent) 30%, transparent);
  color: #fff;
}

/* utility: subtle card */
.card-surface {
  background: var(--bg-surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-card);
}
.card-surface:hover {
  border-color: var(--border-strong);
  background: var(--bg-elevated);
}

/* utility: monospace terminal label */
.mono-label {
  font-family: var(--font-mono);
